import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

import org.springframework.stereotype.Service;

/**
 * Keeps every message sent so far, in memory, for the lifetime of the application.
 */
@Service
public class ContactMessageService {

    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();

    public void add(ContactMessage message) {
        messages.add(0, message);
    }

    /**
     * @return a snapshot of all sent messages, newest first
     */
    public List<ContactMessage> newestFirst() {
        return List.copyOf(messages);
    }
}
