+                }));
+        add(dialog);
+        dialog.open();
+    }
+
+    private void sendIfEnabled() {
+        if (send.isEnabled()) {
+            submit();
+        }
+    }
+
+    private void submit() {
+        inputs.forEach(input -> input.setInvalid(false));
+
+        String senderName = name.getValue().trim();
+        String senderEmail = email.getValue().trim();
+        String senderPhone = phone.getValue().trim();
+        String text = message.getValue().trim();
+
+        if (!validate(senderName, senderEmail, senderPhone, text)) {
+            return;
+        }
+
+        messages.add(new ContactMessage(senderName, senderEmail, senderPhone, text));
+        Notification.show("Message sent");
+        grid.setItems(messages.newestFirst());
+
+        // Clearing fires the value-change listeners, which re-enable Send, so disable it afterwards.
+        inputs.forEach(TextFieldBase::clear);
+        send.setEnabled(false);
+    }
+
+    /**
+     * Marks every field whose rule fails, and returns whether the form may be sent.
+     */
+    private boolean validate(String senderName, String senderEmail, String senderPhone, String text) {
+        boolean valid = true;
+
+        if (senderName.isEmpty()) {
+            markInvalid(name, "Name is required");
+            valid = false;
+        }
+
+        if (!senderEmail.isEmpty()) {
+            if (!EMAIL_PATTERN.matcher(senderEmail).matches()) {
+                markInvalid(email, "Enter a valid e-mail address");
+                valid = false;
+            }
+        } else if (senderPhone.isEmpty()) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (text.isEmpty()) {
+            markInvalid(message, "Message is required");
+            valid = false;
+        } else if (text.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private static void markInvalid(TextFieldBase<?, String> field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+}
