+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+import java.util.regex.Pattern;
+
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
+        properties = "vaadin.launch-browser=false")
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    private static final Pattern ABOUT_URL = Pattern.compile(".*/about$");
+    private static final Pattern CONTACT_URL = Pattern.compile(".*/contact$");
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/contact";
+    }
+
+    @BeforeEach
+    void openContactPage() {
+        page.navigate(getUrl());
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+    }
+
+    @Test
+    void aboutLinkNavigatesWithoutReloadingThePage() {
+        page.evaluate("window.noReloadMarker = 42");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertThat(page).hasURL(ABOUT_URL);
+        Object marker = page.evaluate("window.noReloadMarker");
+        assertEquals(42, ((Number) marker).intValue());
+    }
+
+    @Test
+    void emptyFormShowsValidationErrorsAndSendsNothing() {
+        ButtonElement.getByText(page, "Send").click();
+
+        TextFieldElement.getByLabel(page, "Name").assertInvalid();
+        TextFieldElement.getByLabel(page, "Name").assertErrorMessage("Name is required");
+        EmailFieldElement.getByLabel(page, "Email").assertInvalid();
+        EmailFieldElement.getByLabel(page, "Email").assertErrorMessage("Give an e-mail address or a phone number");
+        NotificationElement.getByText(page, "Message sent").assertClosed();
+    }
+
+    @Test
+    void sendingClearsTheFormDisablesSendAndListsTheMessage() {
+        String name = "Browser Sender";
+        fillForm(name, "", "555-0177", "Sent from the browser");
+
+        ButtonElement.getByText(page, "Send").click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true))).hasValue("");
+        assertThat(page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true))).hasValue("");
+        ButtonElement.getByText(page, "Send").assertDisabled();
+        assertThat(GridElement.get(page).findCell(0, 0).orElseThrow().getCellContentLocator()).hasText(name);
+
+        page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).fill("Again");
+        ButtonElement.getByText(page, "Send").assertEnabled();
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        String name = "Enter Sender";
+        fillForm(name, "", "555-0188", "Sent with Enter");
+
+        page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(GridElement.get(page).findCell(0, 0).orElseThrow().getCellContentLocator()).hasText(name);
+    }
+
+    @Test
+    void leavingWithTypedTextAsksFirstAndKeepEditingStaysOnThePage() {
+        fillForm("Draft Writer", "", "555-0199", "Half written");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        DialogElement.getByHeaderText(page, "Leave this page?").assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        DialogElement.getByHeaderText(page, "Leave this page?").assertClosed();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true))).hasValue("Draft Writer");
+    }
+
+    @Test
+    void discardLeavesForTheAboutView() {
+        fillForm("Discarder", "", "555-0166", "Thrown away");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        DialogElement.getByHeaderText(page, "Leave this page?").assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertThat(page).hasURL(ABOUT_URL);
+    }
+
+    @Test
+    void browserForwardWithTypedTextAsksFirstAndKeepEditingStaysOnThePage() {
+        visitAboutAndComeBackToContact();
+        fillForm("Back Button", "", "555-0133", "Typed before navigating");
+
+        page.goForward();
+
+        DialogElement.getByHeaderText(page, "Leave this page?").assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        DialogElement.getByHeaderText(page, "Leave this page?").assertClosed();
+        assertThat(page).hasURL(CONTACT_URL);
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true))).hasValue("Back Button");
+    }
+
+    @Test
+    void browserForwardWithTypedTextDiscardGoesToTheAboutView() {
+        visitAboutAndComeBackToContact();
+        fillForm("Back Discard", "", "555-0134", "Navigating away");
+
+        page.goForward();
+
+        DialogElement.getByHeaderText(page, "Leave this page?").assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertThat(page).hasURL(ABOUT_URL);
+    }
+
+    @Test
+    void leavingWithAnEmptyFormDoesNotAsk() {
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        DialogElement.getByHeaderText(page, "Leave this page?").assertClosed();
+    }
+
+    @Test
+    void sentMessagesAreStillListedAfterComingBack() {
+        String name = "Returning Sender";
+        fillForm(name, "", "555-0155", "Still here");
+        ButtonElement.getByText(page, "Send").click();
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        assertThat(page.locator("h1")).hasText("About");
+        page.goBack();
+        assertThat(page.locator("h1")).hasText("Contact");
+
+        assertThat(GridElement.get(page).findCell(0, 0).orElseThrow().getCellContentLocator()).hasText(name);
+    }
+
+    /**
+     * Visits About with the About link and comes back with Back, so About is the forward entry.
+     * The visit has to be client-side: a full page load would never reach the view's leave check.
+     */
+    private void visitAboutAndComeBackToContact() {
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        assertThat(page.locator("h1")).hasText("About");
+        page.goBack();
+        assertThat(page.locator("h1")).hasText("Contact");
+    }
+
+    private void fillForm(String name, String email, String phone, String message) {
+        page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).fill(name);
+        page.getByLabel("Email", new Page.GetByLabelOptions().setExact(true)).fill(email);
+        page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).fill(phone);
+        page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill(message);
+    }
+}
