+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private static final String LONG_MESSAGE = "x".repeat(501);
+
+    @Autowired
+    private ContactMessageService messages;
+
+    @BeforeEach
+    void openContactView() {
+        navigate(ContactView.class);
+    }
+
+    @Test
+    void showsHeadingAndEmptyFormWithSendEnabled() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue(name().isEmpty());
+        assertTrue(email().isEmpty());
+        assertTrue(phone().isEmpty());
+        assertTrue(message().isEmpty());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void emptyFormMarksRequiredFieldsAndSendsNothing() {
+        int sentBefore = messages.newestFirst().size();
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse($(Notification.class).exists());
+        assertEquals(sentBefore, messages.newestFirst().size());
+    }
+
+    @Test
+    void invalidEmailIsRejectedEvenWhenPhoneIsGiven() {
+        fill("Alice", "not-an-address", "555-0100", "Hello");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+        assertEquals("Alice", name().getValue());
+    }
+
+    @Test
+    void messageLongerThan500CharactersIsRejected() {
+        fill("Alice", "alice@example.com", "", LONG_MESSAGE);
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals(LONG_MESSAGE, message().getValue());
+    }
+
+    @Test
+    void phoneNumberAloneIsEnough() {
+        fill("Bob", "", "555-0199", "Call me");
+
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals("555-0199", messages.newestFirst().get(0).phone());
+        assertTrue(name().isEmpty());
+    }
+
+    @Test
+    void sendingShowsNotificationAddsRowAndClearsForm() {
+        fill("Carol", "carol@example.com", "", "Hi there");
+
+        test(send()).click();
+
+        assertTrue(notificationShown("Message sent"));
+        assertEquals("Carol", rows().get(0).name());
+        assertEquals("Hi there", rows().get(0).message());
+        assertTrue(name().isEmpty());
+        assertTrue(email().isEmpty());
+        assertTrue(phone().isEmpty());
+        assertTrue(message().isEmpty());
+        assertFalse(send().isEnabled());
+    }
+
+    @Test
+    void editingAnyFieldReEnablesSend() {
+        fill("Dave", "dave@example.com", "", "Hello");
+        test(send()).click();
+        assertFalse(send().isEnabled());
+
+        test(name()).setValue("D");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        fill("Erin", "", "555-0123", "Via Enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals("Erin", rows().get(0).name());
+        assertEquals("Via Enter", rows().get(0).message());
+    }
+
+    @Test
+    void leavingWithTypedTextAsksFirstAndKeepEditingStaysOnView() {
+        fill("Frank", "", "555-0111", "Draft");
+
+        UI.getCurrent().navigate(AboutView.class);
+
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Frank", name().getValue());
+        assertEquals("Draft", message().getValue());
+    }
+
+    @Test
+    void discardLeavesForTheAboutView() {
+        fill("Grace", "", "555-0122", "Draft");
+        UI.getCurrent().navigate(AboutView.class);
+
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotAskAnything() {
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertTrue($(Dialog.class).all().stream().noneMatch(Dialog::isOpened));
+    }
+
+    @Test
+    void sentMessagesAreStillListedAfterComingBack() {
+        fill("Heidi", "", "555-0144", "Remember me");
+        test(send()).click();
+
+        UI.getCurrent().navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals("Heidi", rows().get(0).name());
+        assertEquals("Remember me", rows().get(0).message());
+    }
+
+    private void fill(String name, String email, String phone, String message) {
+        test(name()).setValue(name);
+        test(email()).setValue(email);
+        test(phone()).setValue(phone);
+        test(message()).setValue(message);
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    private boolean notificationShown(String text) {
+        // Notification keeps its text in a property rather than in its element's text nodes.
+        return $(Notification.class).all().stream()
+                .anyMatch(notification -> text.equals(notification.getElement().getProperty("text")));
+    }
+
+    private List<ContactMessage> rows() {
+        @SuppressWarnings("unchecked")
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        return grid.getListDataView().getItems().toList();
+    }
+}
